(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,18071,e=>{"use strict";let t={de:{nav:{home:"Startseite",philosophy:"Philosophie",products:"Produkte",reviews:"Stimmen",contact:"Kontakt",shop:"Zum Shop"},hero:{tag1:"AKAZIENHOLZ",tag2:"NATURKANTE",tag3:"HANDGEFERTIGT",title1:"Naturkunst",title2:"für Ihr Zuhause",description:"Jeder unserer Massivholztische ist ein Unikat — geformt von der Natur, vollendet von Hand. Erleben Sie die unvergleichliche Schönheit von Akazienholz mit Naturkante.",cta1:"Kollektion entdecken",cta2:"Beratung vereinbaren"},philosophy:{subtitle:"UNSERE PHILOSOPHIE",title:"Möbel für Körper & Seele",description1:"Wir sind eine kleine Manufaktur aus dem idyllischen Sonneberg in Thüringen. Unsere Spezialität ist das Besondere. Wir produzieren Ihre ganz exklusiven Möbel — jedes Möbelstück wird in Handarbeit zu Ihrem Unikat.",description2:"Exklusivität und individuelles Design. Die Basis unserer Arbeit stellt dabei die Kommunikation mit dem Kunden dar. Um Ihre Wünsche möglich zu machen, bedarf es eines außergewöhnlichen Kundenservice. Ein Zuhause ist mehr als nur ein Platz, an dem Sie schlafen. Es ist ein Rückzugsort, ein Platz der Familie, wo jeder die Seele baumeln und sich so richtig wohlfühlen kann.",description3:"Kein anderes Material kann mehr Heimlichkeit und Wohnlichkeit erzeugen als Massivholz. Holz ist warm und gibt ein natürliches Gefühl. Möbel zu erzeugen, die nicht nur praktisch und schön zum Anschauen sind, sondern Möbel zum Wohlfühlen — das ist das Ziel von Luisemöbel.",feature1Title:"Massivholz",feature1Desc:"Jedes Stück wird aus hochwertigem Akazienholz gefertigt — langlebig, schön und voller Charakter.",feature2Title:"Handgefertigt",feature2Desc:"Jedes Möbelstück entsteht in Handarbeit in unserer Werkstatt — für unvergleichliche Qualität und Liebe zum Detail.",feature3Title:"Unikat",feature3Desc:"Kein Stück gleicht dem anderen. Die natürliche Maserung und Naturkante machen jeden Tisch zu einem einzigartigen Meisterwerk."},products:{subtitle:"UNSERE PRODUKTE",title:"Mit Leidenschaft Gefertigt",description:"Entdecken Sie unsere Kollektion handgefertigter Massivholzmöbel. Von Esstischen bis Konsolen — jedes Stück erzählt seine eigene Geschichte durch die natürliche Schönheit des Akazienholzes.",categories:[{name:"Esstische",description:"Beeindruckende Massivholz-Esstische mit Naturkante — das Herzstück Ihres Esszimmers.",link:"https://luisemoebel.com/product-category/esstische/"},{name:"Couchtische",description:"Elegante Couchtische, die Wärme und Charakter in Ihr Wohnzimmer bringen.",link:"https://luisemoebel.com/product-category/kaffeetische/"},{name:"Konsolen",description:"Stilvolle Konsolen für Ihren Flur oder Eingangsbereich — ein warmes Willkommen zu Hause.",link:"https://luisemoebel.com/product-category/konsolen/"},{name:"Sitzmöbel",description:"Bequeme Sitzmöbel, die Ihre Massivholzmöbel perfekt ergänzen.",link:"https://luisemoebel.com/product-category/sitzmoebel/"},{name:"Dekoration",description:"Einzigartige Dekorationsstücke aus Naturholz — kleine Kunstwerke für Ihr Zuhause.",link:"https://luisemoebel.com/product-category/dekoration/"},{name:"Holzwaschbecken",description:"Exklusive Holzwaschbecken — ein natürliches Highlight für Ihr Badezimmer.",link:"https://luisemoebel.com/product-category/holzwaschbecken/"}],viewShop:"Im Shop Ansehen"},wood:{subtitle:"UNSER HOLZ",title:"Der Regenbaum — Samanea Saman",description1:"Für die Produktion Ihrer Möbel verwenden wir überwiegend das Holz des Regenbaums (Samanea Saman). Dieses ist auch unter den Namen Suar- oder Chamcha-Holz bekannt. Der Regenbaum gehört zur Familie der Akazienbäume.",description2:"Das Suarholz des Regenbaums besticht in erster Linie durch seine faszinierende und kontrastreiche Maserung. Diese ist dabei von Baum zu Baum unterschiedlich, so dass jedes Möbelstück ein Unikat darstellt. Das Holz gilt dabei als sehr stabil und leicht zu verarbeiten, so dass sich einzigartige Möbelstücke herstellen lassen. Seine natürlichen Öle schützen es vor Schädlingen und Verrottung.",description3:"Unser Holz stammt aus dem Norden Thailands. Der Regenbaum stammt ursprünglich aus Südamerika. Er hat sich mit der Zeit jedoch auch in vielen Gegenden Asiens ausgebreitet. Das warme Klima und der ausreichende Niederschlag im Norden Thailands bieten optimale Bedingungen für das Wachstum des Regenbaums.",sustainability:"Nachhaltigkeit",sustainabilityDesc:"Beim Regenbaum handelt es sich um Tropenholz. Jedoch zählt dieses nicht zu den bedrohten und geschützten Arten. Regenbäume sind dabei in Thailand nicht Teil der natürlichen Regenwälder, sondern ein Nebenprodukt beim Ausbau von Infrastruktur. Sie dienen vor allem als Schattenspender auf Plantagen und an Straßen. So entsteht nachhaltig neuer Lebensraum."},reviews:{subtitle:"KUNDENSTIMMEN",title:"Was Unsere Kunden Sagen",description:"Die Zufriedenheit unserer Kunden ist unser größter Lohn. Lesen Sie, was sie über ihre Erfahrung mit Luisemöbel berichten.",googleLabel:"Google Bewertung",items:[{name:"Teedee",rating:5,text:"Als ich mir überlegt habe, was ich bei der Kaufabwicklung noch besser machen würde, ist mir wirklich nichts eingefallen. Für einen echt tollen Preis haben wir..."},{name:"S. Stefan - Buzz",rating:5,text:"Ich habe nach langer Überlegung einen Esstisch bestellt. Die Qualität ist klasse! Die Oberfläche der Tischplatte ist ein absoluter Hingucker und meine Familie..."},{name:"Andre Nolte",rating:5,text:"Herr Müller, war schon beim ersten Gespräch sehr freundlich. Eine sehr kompetente Beratung. Lieferung sehr zeitnah. Preise sind top. Qualität des Tisches..."},{name:"Philipp Huber",rating:5,text:"1A Service, Preis-Leistung unübertrefflich, freundlicher und kundenorientierter Service, flexible Lösungen und Ideen, auch im After-Sales bei Rückfragen zur Pflege gerne behilflich. Gerne wieder!"},{name:"Madlin Dittmar",rating:4,text:"Wir sind im November 2020 via eBay auf LUISEMÖBEL aufmerksam geworden. Durch seine sehr hohe Kundenorientierung hatten wir bereits nach dem ersten telefonischen..."},{name:"Matthias Hoeller",rating:5,text:"Herr Müller von Luisemöbel hat uns außerordentlich kompetent und geduldig über den Kauf eines Esstisches mit Naturholzplatte beraten und sich jede erdenkliche Mühe gegeben. Jederzeit empfehlenswert!"},{name:"Dr. Jens Barthel",rating:5,text:"Außergewöhnliche Beratung und Betreuung mit einem exzellenten Service."},{name:"Anna Baum",rating:5,text:"Top Qualität gute Beratung nettes Personal und trotz der Entfernung (470km) super Lieferung. Kann ich nur weiterempfehlen."},{name:"Ramon Langbein",rating:5,text:"Sehr gut sehr kundenfreundlich."},{name:"Joker One",rating:5,text:"Das Akazieholz hat wirklich eine tolle Maserung und das schöne ist, dass diese in einem Stück zu sehen ist."},{name:"Max Müller",rating:5,text:"Handwerklich schön gemacht wunderschön Tische und vieles mehr..."},{name:"Thomas Hirt",rating:5,text:"Sehr schöne Ideen und kompetente Beratung."}]},contact:{subtitle:"KONTAKT",title:"Nehmen Sie Kontakt Auf",description:"Haben Sie Fragen zu unseren Möbeln oder wünschen Sie eine persönliche Beratung? Wir sind für Sie da.",phone:"Telefon",mobile:"Mobil / WhatsApp",email:"E-Mail",skype:"Skype",address:"Adresse",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Thüringen",callUs:"Anrufen",writeUs:"Schreiben Sie Uns",visitShop:"Shop Besuchen"},footer:{tagline:"Möbel für Körper & Seele — Nicht nur praktisch und schön zum Anschauen, sondern Möbel zum Wohlfühlen. Handgefertigte Massivholzmöbel für anspruchsvolle Kunden mit einem außergewöhnlichen Geschmack.",links:{home:"Startseite",about:"Über uns",wood:"Unser Holz",info:"Informationen",blog:"Blog",contact:"Kontakt",shop:"Shop",privacy:"Datenschutz",terms:"AGB",imprint:"Impressum"},copyright:"Copyright 2026 © LUISEMOEBEL.com. Alle Rechte vorbehalten.",prices:"*) Alle Preise inkl. der gesetzlichen MwSt. zzgl. Versandkosten. Die durchgestrichenen Preise entsprechen dem bisherigen Preis in diesem Online-Shop."},cookie:{title:"Cookie-Einstellungen",description:"Wir verwenden Cookies, um Ihnen die bestmögliche Erfahrung auf unserer Website zu bieten. Durch die weitere Nutzung der Website stimmen Sie der Verwendung von Cookies zu.",accept:"Alle akzeptieren",decline:"Nur notwendige",settings:"Einstellungen",learnMore:"Mehr erfahren"},subpages:{backToHome:"Zurück zur Startseite",ueberUns:{heroTitle:"Über Uns",heroSubtitle:"SEIT ÜBER 25 JAHREN",introTitle:"Unsere Geschichte",introP1:"Luisemöbel ist mehr als nur ein Möbelhersteller — wir sind eine Manufaktur mit Herz und Seele. Gegründet im idyllischen Sonneberg, Thüringen, haben wir uns der Kunst verschrieben, aus natürlichem Akazienholz einzigartige Möbelstücke zu schaffen.",introP2:"Seit über 25 Jahren verbinden wir traditionelles Handwerk mit modernem Design. Jedes Möbelstück, das unsere Werkstatt verlässt, trägt die Handschrift unserer erfahrenen Kunsthandwerker und die natürliche Schönheit des Holzes.",introP3:"Unsere Philosophie ist einfach: Wir glauben daran, dass Möbel mehr sein sollten als nur funktionale Gegenstände. Sie sollen ein Zuhause warmer und einladender machen — Möbel für Körper und Seele.",valuesTitle:"Unsere Werte",value1Title:"Massivholz",value1Desc:"Wir verwenden ausschließlich hochwertiges Akazienholz (Regenbaum) — kein Furnier, kein Spanholz. Massiv, natürlich und voller Charakter.",value2Title:"Handgefertigt",value2Desc:"Jedes Möbelstück entsteht in sorgfältiger Handarbeit in unserer Werkstatt in Sonneberg. Traditionelles Handwerk meets individuelle Gestaltung.",value3Title:"Unikat",value3Desc:"Kein Stück gleicht dem anderen. Die natürliche Maserung und die einzigartige Naturkante machen jeden Tisch zu einem unverwechselbaren Meisterwerk.",workshopTitle:"Unsere Werkstatt",workshopDesc:"In unserer Werkstatt in Sonneberg, Thüringen, entstehen Ihre TraumMöbel. Hier arbeiten erfahrene Kunsthandwerker mit Leidenschaft und Präzision an jedem einzelnen Stück. Von der Holzauswahl bis zur letzten Politur — jeder Schritt wird mit größter Sorgfalt durchgeführt.",workshopDesc2:"Wir legen besonderen Wert auf die Kommunikation mit unseren Kunden. Denn nur wenn wir Ihre Wünsche genau verstehen, können wir Möbel schaffen, die wirklich zu Ihnen passen. Persönliche Beratung und individueller Service sind für uns keine Schlagworte, sondern gelebte Praxis.",ctaTitle:"Entdecken Sie unsere Kollektion",ctaDesc:"Besuchen Sie unseren Online-Shop und finden Sie Ihr nächstes TraumMöbelstück.",ctaButton:"Zum Shop"},holz:{heroTitle:"Unser Holz",heroSubtitle:"NATUR PUR",introTitle:"Der Regenbaum — Samanea Saman",introP1:"Für die Produktion Ihrer Möbel verwenden wir überwiegend das Holz des Regenbaums (Samanea Saman). Dieses ist auch unter den Namen Suar- oder Chamcha-Holz bekannt. Der Regenbaum gehört zur Familie der Akazienbäume (Fabaceae, Unterfamilie Mimosoideae).",introP2:"Das Suarholz des Regenbaums besticht in erster Linie durch seine faszinierende und kontrastreiche Maserung. Diese ist dabei von Baum zu Baum unterschiedlich, so dass jedes Möbelstück ein Unikat darstellt. Das Holz gilt dabei als sehr stabil und leicht zu verarbeiten, so dass sich einzigartige Möbelstücke herstellen lassen. Seine natürlichen Öle schützen es vor Schädlingen und Verrottung.",acaciaTitle:"Die Akazienfamilie",acaciaDesc:"Der Regenbaum (Samanea Saman) gehört zur Familie der Fabaceae (Schmetterlingsblütler) und zur Unterfamilie der Mimosoideae. Obwohl er umgangssprachlich oft als Akazie bezeichnet wird, ist er genaugenommen ein naher Verwandter der Akazien. Die Familie der Mimosoideae umfasst etwa 80 Gattungen mit rund 3.200 Arten, die vor allem in den Tropen und Subtropen verbreitet sind.",acaciaDesc2:"Charakteristisch für diese Familie sind die gefiederten Blätter und die kugeligen Blütenstände. Der Regenbaum kann beeindruckende Ausmaße erreichen: Eine Kronenausbreitung von bis zu 40 Metern und ein Stammdurchmesser von über 2 Metern sind keine Seltenheit.",originTitle:"Herkunft: Nord-Thailand",originDesc:"Unser Holz stammt aus dem Norden Thailands. Der Regenbaum stammt ursprünglich aus Südamerika, hat sich aber im Laufe der Zeit auch in vielen Gegenden Asiens ausgebreitet. Das warme Klima und der ausreichende Niederschlag im Norden Thailands bieten optimale Bedingungen für das Wachstum des Regenbaums.",originDesc2:"In Nord-Thailand wächst der Regenbaum hauptsächlich auf Plantagen und an Straßen, wo er als Schattenspender dient. Die Bäume werden geerntet, wenn sie ihr natürliches Alter erreicht haben oder wenn sie aus Gründen der Infrastrukturentwicklung weichen müssen.",sustainabilityTitle:"Nachhaltigkeit",sustainabilityP1:"Beim Regenbaum handelt es sich um Tropenholz. Jedoch zählt dieses nicht zu den bedrohten und geschützten Arten. Regenbäume sind dabei in Thailand nicht Teil der natürlichen Regenwälder, sondern ein Nebenprodukt beim Ausbau von Infrastruktur.",sustainabilityP2:"Sie dienen vor allem als Schattenspender auf Plantagen und an Straßen. So entsteht nachhaltig neuer Lebensraum. Der Regenbaum wächst zudem sehr schnell und kann innerhalb von 15–20 Jahren eine erntefähige Größe erreichen. Dies macht ihn zu einer nachhaltigen Holzquelle, die nicht auf Kosten des Regenwaldes geht.",propertiesTitle:"Holzeigenschaften",prop1Title:"Härtegrad",prop1Desc:"Mittelhart bis hart (Brinell-Härte ca. 3,5–4,0), ideal für Möbel mit hoher Beanspruchung.",prop2Title:"Maserung",prop2Desc:"Kontrastreich und einzigartig — von warmen Goldtönen bis hin zu tiefen Braun- und Rottönen.",prop3Title:"Natürlicher Schutz",prop3Desc:"Natürliche Öle im Holz schützen vor Schädlingen und Verrottung, ohne chemische Behandlung.",prop4Title:"Formstabilität",prop4Desc:"Trotz natürlicher Eigenschaften ist das Holz bei richtiger Trocknung und Verarbeitung sehr formstabil."},kontakt:{heroTitle:"Kontakt",heroSubtitle:"WIR SIND FÜR SIE DA",phoneTitle:"Telefon",phoneValue:"+49 36 75 40 22 92",mobileTitle:"Mobil / WhatsApp",mobileValue:"+49 16 04 40 26 92",emailTitle:"E-Mail",emailValue:"info@luisemoebel.com",addressTitle:"Adresse",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Thüringen",hoursTitle:"Geschäftszeiten",hoursWeekday:"Montag — Freitag: 9:00 – 18:00 Uhr",hoursSaturday:"Samstag: nach Vereinbarung",hoursSunday:"Sonntag: geschlossen",formTitle:"Schreiben Sie Uns",formName:"Ihr Name",formEmail:"Ihre E-Mail",formSubject:"Betreff",formMessage:"Ihre Nachricht",formSend:"Nachricht Senden",formNote:"* Dieses Formular dient nur zur Kontaktaufnahme. Es wird keine Datenübertragung durchgeführt.",mapTitle:"So Finden Sie Uns",mapButton:"In Google Maps Öffnen",visitShop:"Shop Besuchen"},datenschutz:{heroTitle:"Datenschutzerklärung",heroSubtitle:"RECHTLICHE INFORMATIONEN",sections:[{title:"1. Datenschutz auf einen Blick",paragraphs:["Allgemeine Hinweise: Die folgenden Hinweise geben einen einfachen Überblick darüber, was mit Ihren personenbezogenen Daten passiert, wenn Sie diese Website besuchen. Personenbezogene Daten sind alle Daten, mit denen Sie persönlich identifiziert werden können.","Datenerfassung auf dieser Website: Diese Website wird als statische Seite ohne Server-seitige Datenverarbeitung betrieben. Es werden keine personenbezogenen Daten in Datenbanken gespeichert. Kontaktformulare dienen nur der Anzeige und übermitteln keine Daten.","Cookies: Diese Website verwendet technische Cookies, die für den Betrieb der Seite notwendig sind (z.B. Cookie-Einwilligung). Es werden keine Tracking-Cookies oder Analyse-Tools eingesetzt."]},{title:"2. Verantwortliche Stelle",paragraphs:["Verantwortlich für die Datenverarbeitung auf dieser Website ist:\n\nLuisemöbel\nJulius-Heß-Straße 9\n96515 Sonneberg\nThüringen, Deutschland\n\nTelefon: +49 36 75 40 22 92\nE-Mail: info@luisemoebel.com"]},{title:"3. Hosting",paragraphs:["Diese Website wird auf GitHub Pages gehostet. Beim Aufruf der Website werden durch den Hosting-Anbieter automatisch Informationen allgemeiner Natur erfasst, wie z.B. die IP-Adresse des aufrufenden Rechners. Diese Daten werden ausschließlich technisch notwendig erhoben."]},{title:"4. Ihre Rechte",paragraphs:["Sie haben jederzeit das Recht, unentgeltlich Auskunft über Herkunft, Empfänger und Zweck Ihrer gespeicherten personenbezogenen Daten zu erhalten. Sie haben außerdem ein Recht, die Berichtigung oder Löschung dieser Daten zu verlangen. Wenn Sie eine Einwilligung zur Datenverarbeitung erteilt haben, können Sie diese Einwilligung jederzeit für die Zukunft widerrufen.","Hierzu sowie zu weiteren Fragen zum Thema Datenschutz können Sie sich jederzeit an uns wenden."]},{title:"5. Cookies",paragraphs:["Diese Website verwendet technisch notwendige Cookies, um den Betrieb der Seite zu gewährleisten. Der Cookie für die Cookie-Einwilligung (luisemoebel_cookie_consent) speichert lediglich Ihre Entscheidung bezüglich der Cookie-Nutzung.","Es werden keine Tracking-Cookies, Marketing-Cookies oder Cookies von Drittanbietern eingesetzt."]},{title:"6. Externe Links",paragraphs:["Diese Website enthält Links zu externen Websites (z.B. luisemoebel.com Shop, Google Maps). Beim Klick auf diese Links verlassen Sie unsere Website. Für die Datenverarbeitung auf den verlinkten Seiten sind deren jeweiligen Betreiber verantwortlich."]},{title:"7. SSL-Verschlüsselung",paragraphs:['Diese Seite nutzt aus Sicherheitsgründen eine SSL-Verschlüsselung. Eine verschlüsselte Verbindung erkennen Sie daran, dass die Adresszeile des Browsers von „http://" auf „https://" wechselt.']}]},agb:{heroTitle:"Allgemeine Geschäftsbedingungen",heroSubtitle:"RECHTLICHE INFORMATIONEN",sections:[{title:"1. Geltungsbereich",paragraphs:["Diese Allgemeinen Geschäftsbedingungen (AGB) gelten für alle Verträge zwischen Luisemöbel, Julius-Heß-Straße 9, 96515 Sonneberg, und dem Kunden. Abweichende Bedingungen des Kunden werden nicht anerkannt, es sei denn, Luisemöbel stimmt ihrer Geltung ausdrücklich schriftlich zu."]},{title:"2. Vertragsabschluss",paragraphs:['Die Darstellung der Produkte auf der Website stellt kein rechtlich bindendes Angebot dar, sondern einen unverbindlichen Online-Katalog. Durch Anklicken des Buttons „Kaufen" geben Sie eine verbindliche Bestellung der im Warenkorb enthaltenen Waren ab.',"Die Bestätigung des Eingangs der Bestellung erfolgt zusammen mit der Vertragsannahme automatisch per E-Mail unmittelbar nach dem Absenden der Bestellung."]},{title:"3. Preise und Versandkosten",paragraphs:["Alle Preise sind Endverbraucherpreise und enthalten die gesetzliche Mehrwertsteuer. Versandkosten werden gesondert ausgewiesen und sind vom Kunden zu tragen."]},{title:"4. Lieferung",paragraphs:["Lieferzeiten werden auf der Produktseite und in der Bestellbestätigung angegeben. Da es sich um handgefertigte Einzelstücke handelt, können Lieferzeiten variieren. Luisemöbel informiert den Kunden über den voraussichtlichen Liefertermin.","Die Lieferung erfolgt innerhalb Deutschlands und in ausgewählte EU-Länder. Die Versandkosten richten sich nach dem Lieferort."]},{title:"5. Eigentumsvorbehalt",paragraphs:["Die gelieferte Ware bleibt bis zur vollständigen Bezahlung Eigentum von Luisemöbel."]},{title:"6. Widerrufsrecht",paragraphs:["Verbraucher haben das Recht, binnen vierzehn Tagen ohne Angabe von Gründen den Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag, an dem Sie oder ein von Ihnen benannter Dritter die Waren in Besitz genommen haben.","Für maßgefertigte Möbelstücke, die nach Kundenspezifikationen angefertigt werden, kann das Widerrufsrecht eingeschränkt sein."]},{title:"7. Gewährleistung",paragraphs:["Die Gewährleistung erfolgt nach den gesetzlichen Bestimmungen. Bei Vorliegen eines Mangels hat der Kunde die Wahl zwischen Nacherfüllung durch Nachbesserung oder Ersatzlieferung.","Natürliche Merkmale des Holzes wie Maserung, Astlöcher, Risse oder Farbunterschiede stellen keine Mängel dar, sondern sind Ausdruck der Einzigartigkeit natürlichen Holzes."]},{title:"8. Pflegehinweise",paragraphs:["Massivholzmöbel erfordern eine angemessene Pflege. Detaillierte Pflegehinweise werden mit jedem Möbelstück geliefert. Unsachgemäße Pflege führt zum Verlust von Gewährleistungsansprüchen."]},{title:"9. Datenschutz",paragraphs:["Die Erhebung und Verarbeitung personenbezogener Daten erfolgt gemäß unserer Datenschutzerklärung."]},{title:"10. Gerichtsstand",paragraphs:["Gerichtsstand ist Sonneberg, Thüringen, Deutschland. Es gilt das Recht der Bundesrepublik Deutschland."]}]},impressum:{heroTitle:"Impressum",heroSubtitle:"RECHTLICHE ANGABEN",companyName:"Luisemöbel",companyAddress:"Julius-Heß-Straße 9\n96515 Sonneberg\nThüringen, Deutschland",contactTitle:"Kontakt",contactPhone:"Telefon: +49 36 75 40 22 92",contactMobile:"Mobil: +49 16 04 40 26 92",contactEmail:"E-Mail: info@luisemoebel.com",vatTitle:"Umsatzsteuer-Identifikationsnummer",vatValue:"Gemäß § 27a Umsatzsteuergesetz:\nDE 351 888 707",responsibleTitle:"Verantwortlich für den Inhalt nach § 55 Abs. 2 RStV",responsibleValue:"Ralf Müller\nJulius-Heß-Straße 9\n96515 Sonneberg",disputeTitle:"EU-Streitschlichtung",disputeDesc:"Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: https://ec.europa.eu/consumers/odr/. Unsere E-Mail-Adresse finden Sie oben im Impressum.",consumerTitle:"Verbraucherstreitbeilegung",consumerDesc:"Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.",liabilityTitle:"Haftung für Inhalte",liabilityDesc:"Als Diensteanbieter sind wir gemäß § 7 Abs.1 TMG für eigene Inhalte auf diesen Seiten nach den allgemeinen Gesetzen verantwortlich. Nach §§ 8 bis 10 TMG sind wir als Diensteanbieter jedoch nicht verpflichtet, übermittelte oder gespeicherte fremde Informationen zu überwachen.",linksTitle:"Haftung für Links",linksDesc:"Unser Angebot enthält Links zu externen Websites Dritter, auf deren Inhalte wir keinen Einfluss haben. Deshalb können wir für diese fremden Inhalte auch keine Gewähr übernehmen. Für die Inhalte der verlinkten Seiten ist stets der jeweilige Anbieter oder Betreiber der Seiten verantwortlich.",copyrightTitle:"Urheberrecht",copyrightDesc:"Die durch die Seitenbetreiber erstellten Inhalte und Werke auf diesen Seiten unterliegen dem deutschen Urheberrecht. Die Vervielfältigung, Bearbeitung, Verbreitung und jede Art der Verwertung außerhalb der Grenzen des Urheberrechtes bedürfen der schriftlichen Zustimmung des jeweiligen Autors bzw. Erstellers."}}},en:{nav:{home:"Home",philosophy:"Philosophy",products:"Products",reviews:"Reviews",contact:"Contact",shop:"Go to Shop"},hero:{tag1:"ACACIA WOOD",tag2:"NATURAL EDGE",tag3:"HANDCRAFTED",title1:"Natural Art",title2:"for Your Home",description:"Each of our solid wood tables is a unique piece — shaped by nature, perfected by hand. Experience the incomparable beauty of acacia wood with a natural edge.",cta1:"Discover the Collection",cta2:"Book a Consultation"},philosophy:{subtitle:"OUR PHILOSOPHY",title:"Furniture for Body & Soul",description1:"We are a small manufactory from the idyllic town of Sonneberg in Thuringia, Germany. Our specialty is the extraordinary. We produce your exclusive furniture — each piece handcrafted into a unique work of art.",description2:"Exclusivity and individual design. The foundation of our work is communication with our customers. Making your wishes come true requires exceptional customer service. A home is more than just a place to sleep — it is a retreat, a place for family, where you can let your soul roam free and truly feel at ease.",description3:"No other material can create more warmth and coziness than solid wood. Wood is warm and gives a natural feeling. Our goal is to create furniture that is not only practical and beautiful to look at, but furniture that makes you feel good.",feature1Title:"Solid Wood",feature1Desc:"Every piece is crafted from premium acacia wood — durable, beautiful, and full of character.",feature2Title:"Handcrafted",feature2Desc:"Each furniture piece is made by hand in our workshop, ensuring unparalleled quality and attention to detail.",feature3Title:"Unique",feature3Desc:"No two pieces are alike. The natural grain and live edge make every table a one-of-a-kind masterpiece."},products:{subtitle:"OUR PRODUCTS",title:"Crafted with Passion",description:"Discover our collection of handcrafted solid wood furniture. From dining tables to console tables — each piece tells its own story through the natural beauty of acacia wood.",categories:[{name:"Dining Tables",description:"Impressive solid wood dining tables with natural live edge — the centerpiece of your dining room.",link:"https://luisemoebel.com/product-category/esstische/"},{name:"Coffee Tables",description:"Elegant coffee tables that bring warmth and character to your living space.",link:"https://luisemoebel.com/product-category/kaffeetische/"},{name:"Console Tables",description:"Stylish console tables for your hallway or entrance — a warm welcome home.",link:"https://luisemoebel.com/product-category/konsolen/"},{name:"Seating",description:"Comfortable seating furniture that perfectly complements your solid wood pieces.",link:"https://luisemoebel.com/product-category/sitzmoebel/"},{name:"Decoration",description:"Unique decorative pieces made from natural wood — small works of art for your home.",link:"https://luisemoebel.com/product-category/dekoration/"},{name:"Wooden Sinks",description:"Exclusive wooden washbasins — a natural highlight for your bathroom.",link:"https://luisemoebel.com/product-category/holzwaschbecken/"}],viewShop:"View in Shop"},wood:{subtitle:"OUR WOOD",title:"The Rain Tree — Samanea Saman",description1:"For the production of your furniture, we primarily use the wood of the Rain Tree (Samanea Saman), also known as Suar or Chamcha wood. The Rain Tree belongs to the Acacia family.",description2:"Suar wood captivates above all with its fascinating and contrasting grain, which varies from tree to tree, making each piece of furniture unique. The wood is considered very stable and easy to work with, allowing for the creation of truly unique furniture pieces. Its natural oils protect it from pests and decay.",description3:"Our wood originates from Northern Thailand. The Rain Tree is originally from South America but has spread to many parts of Asia over time. The warm climate and abundant rainfall in Northern Thailand provide optimal conditions for the growth of the Rain Tree.",sustainability:"Sustainability",sustainabilityDesc:"The Rain Tree is tropical wood, but it does not belong to the endangered or protected species. Rain Trees in Thailand are not part of the natural rainforest — they are a byproduct of infrastructure development. They primarily serve as shade providers on plantations and along roads, sustainably creating new habitat."},reviews:{subtitle:"CUSTOMER VOICES",title:"What Our Customers Say",description:"Our customers' satisfaction is our greatest reward. Read what they have to say about their experience with Luisemöbel.",googleLabel:"Google Review",items:[{name:"Teedee",rating:5,text:"When I thought about what could be improved about the purchasing process, I really couldn't think of anything. For a truly great price, we received..."},{name:"S. Stefan - Buzz",rating:5,text:"After long consideration, I ordered a dining table. The quality is top class! The surface of the tabletop is an absolute eye-catcher and my family..."},{name:"Andre Nolte",rating:5,text:"Mr. Müller was very friendly from the very first conversation. Extremely competent advice. Very prompt delivery. Prices are top. Quality of the table..."},{name:"Philipp Huber",rating:5,text:"1A Service, unbeatable price-performance ratio, friendly and customer-oriented service, flexible solutions and ideas, also helpful in after-sales with questions about care. Gladly again!"},{name:"Madlin Dittmar",rating:4,text:"We discovered LUISEMÖBEL via eBay in November 2020. Due to his very high customer orientation, already after the first phone call, we had..."},{name:"Matthias Hoeller",rating:5,text:"Mr. Müller from Luisemöbel advised us extraordinarily competently and patiently on the purchase of a dining table with a natural wood top and made every effort. Highly recommended anytime!"},{name:"Dr. Jens Barthel",rating:5,text:"Exceptional advice and support with excellent service."},{name:"Anna Baum",rating:5,text:"Top quality, good advice, nice staff and despite the distance (470km) super delivery. I can only recommend."},{name:"Ramon Langbein",rating:5,text:"Very good, very customer-friendly."},{name:"Joker One",rating:5,text:"The acacia wood really has a beautiful grain and the nice thing is that it can be seen in one piece."},{name:"Max Müller",rating:5,text:"Beautifully crafted, wonderful tables and much more..."},{name:"Thomas Hirt",rating:5,text:"Very beautiful ideas and competent advice."}]},contact:{subtitle:"CONTACT",title:"Get in Touch",description:"Do you have questions about our furniture or would you like a personal consultation? We are here for you.",phone:"Phone",mobile:"Mobile / WhatsApp",email:"Email",skype:"Skype",address:"Address",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Thuringia, Germany",callUs:"Call Us",writeUs:"Write Us",visitShop:"Visit Our Shop"},footer:{tagline:"Furniture for Body & Soul — Not only practical and beautiful to look at, but furniture that makes you feel good. Handcrafted solid wood furniture for discerning customers with exceptional taste.",links:{home:"Home",about:"About Us",wood:"Our Wood",info:"Information",blog:"Blog",contact:"Contact",shop:"Shop",privacy:"Privacy Policy",terms:"Terms & Conditions",imprint:"Imprint"},copyright:"Copyright 2026 © LUISEMOEBEL.com. All rights reserved.",prices:"*) All prices include statutory VAT plus shipping costs. The crossed-out prices correspond to the previous price in this online shop."},cookie:{title:"Cookie Settings",description:"We use cookies to provide you with the best possible experience on our website. By continuing to use the website, you agree to the use of cookies.",accept:"Accept All",decline:"Essential Only",settings:"Settings",learnMore:"Learn More"},subpages:{backToHome:"Back to Home",ueberUns:{heroTitle:"About Us",heroSubtitle:"FOR OVER 25 YEARS",introTitle:"Our Story",introP1:"Luisemöbel is more than just a furniture manufacturer — we are a manufactory with heart and soul. Founded in the idyllic town of Sonneberg, Thuringia, we have dedicated ourselves to the art of creating unique furniture pieces from natural acacia wood.",introP2:"For over 25 years, we have combined traditional craftsmanship with modern design. Every piece of furniture that leaves our workshop bears the signature of our experienced artisans and the natural beauty of the wood.",introP3:"Our philosophy is simple: we believe that furniture should be more than just functional objects. They should make a home warmer and more inviting — furniture for body and soul.",valuesTitle:"Our Values",value1Title:"Solid Wood",value1Desc:"We use only premium acacia wood (Rain Tree) — no veneer, no particle board. Solid, natural, and full of character.",value2Title:"Handcrafted",value2Desc:"Each furniture piece is crafted by hand with care in our workshop in Sonneberg. Traditional craftsmanship meets individual design.",value3Title:"Unique",value3Desc:"No two pieces are alike. The natural grain and unique live edge make every table an unmistakable masterpiece.",workshopTitle:"Our Workshop",workshopDesc:"In our workshop in Sonneberg, Thuringia, your dream furniture is created. Here, experienced artisans work with passion and precision on every single piece. From wood selection to the final polish — every step is carried out with the utmost care.",workshopDesc2:"We place special emphasis on communication with our customers. Because only when we understand your wishes exactly can we create furniture that truly suits you. Personal consultation and individual service are not buzzwords for us, but lived practice.",ctaTitle:"Discover Our Collection",ctaDesc:"Visit our online shop and find your next dream piece of furniture.",ctaButton:"Go to Shop"},holz:{heroTitle:"Our Wood",heroSubtitle:"PURE NATURE",introTitle:"The Rain Tree — Samanea Saman",introP1:"For the production of your furniture, we primarily use the wood of the Rain Tree (Samanea Saman), also known as Suar or Chamcha wood. The Rain Tree belongs to the Acacia family (Fabaceae, subfamily Mimosoideae).",introP2:"Suar wood captivates above all with its fascinating and contrasting grain, which varies from tree to tree, making each piece of furniture unique. The wood is considered very stable and easy to work with, allowing for the creation of truly unique furniture pieces. Its natural oils protect it from pests and decay.",acaciaTitle:"The Acacia Family",acaciaDesc:"The Rain Tree (Samanea Saman) belongs to the family Fabaceae (legumes) and the subfamily Mimosoideae. Although it is commonly referred to as acacia, it is technically a close relative of the acacias. The Mimosoideae family comprises about 80 genera with around 3,200 species, distributed mainly in tropical and subtropical regions.",acaciaDesc2:"Characteristic of this family are the pinnate leaves and globular flower clusters. The Rain Tree can reach impressive dimensions: a crown spread of up to 40 meters and a trunk diameter of over 2 meters are not uncommon.",originTitle:"Origin: Northern Thailand",originDesc:"Our wood originates from Northern Thailand. The Rain Tree is originally from South America but has spread to many parts of Asia over time. The warm climate and abundant rainfall in Northern Thailand provide optimal conditions for the growth of the Rain Tree.",originDesc2:"In Northern Thailand, the Rain Tree grows mainly on plantations and along roads, where it serves as a shade provider. The trees are harvested when they have reached their natural age or when they need to make way for infrastructure development.",sustainabilityTitle:"Sustainability",sustainabilityP1:"The Rain Tree is tropical wood, but it does not belong to the endangered or protected species. Rain Trees in Thailand are not part of the natural rainforest — they are a byproduct of infrastructure development.",sustainabilityP2:"They primarily serve as shade providers on plantations and along roads, sustainably creating new habitat. The Rain Tree also grows very quickly and can reach a harvestable size within 15–20 years. This makes it a sustainable source of wood that does not come at the expense of the rainforest.",propertiesTitle:"Wood Properties",prop1Title:"Hardness",prop1Desc:"Medium-hard to hard (Brinell hardness approx. 3.5–4.0), ideal for furniture with high wear.",prop2Title:"Grain",prop2Desc:"Contrasting and unique — from warm golden tones to deep brown and red hues.",prop3Title:"Natural Protection",prop3Desc:"Natural oils in the wood protect against pests and decay, without chemical treatment.",prop4Title:"Dimensional Stability",prop4Desc:"Despite its natural characteristics, the wood is very dimensionally stable when properly dried and processed."},kontakt:{heroTitle:"Contact",heroSubtitle:"WE ARE HERE FOR YOU",phoneTitle:"Phone",phoneValue:"+49 36 75 40 22 92",mobileTitle:"Mobile / WhatsApp",mobileValue:"+49 16 04 40 26 92",emailTitle:"Email",emailValue:"info@luisemoebel.com",addressTitle:"Address",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Thuringia, Germany",hoursTitle:"Business Hours",hoursWeekday:"Monday — Friday: 9:00 AM – 6:00 PM",hoursSaturday:"Saturday: by appointment",hoursSunday:"Sunday: closed",formTitle:"Write to Us",formName:"Your Name",formEmail:"Your Email",formSubject:"Subject",formMessage:"Your Message",formSend:"Send Message",formNote:"* This form is for display purposes only. No data will be transmitted.",mapTitle:"How to Find Us",mapButton:"Open in Google Maps",visitShop:"Visit Our Shop"},datenschutz:{heroTitle:"Privacy Policy",heroSubtitle:"LEGAL INFORMATION",sections:[{title:"1. Privacy at a Glance",paragraphs:["General Notes: The following notes provide a simple overview of what happens to your personal data when you visit this website. Personal data is any data that can be used to identify you personally.","Data Collection on This Website: This website is operated as a static page without server-side data processing. No personal data is stored in databases. Contact forms are for display purposes only and do not transmit any data.","Cookies: This website uses technical cookies that are necessary for the operation of the site (e.g., cookie consent). No tracking cookies or analytics tools are used."]},{title:"2. Responsible Party",paragraphs:["The responsible party for data processing on this website is:\n\nLuisemöbel\nJulius-Heß-Straße 9\n96515 Sonneberg\nThuringia, Germany\n\nPhone: +49 36 75 40 22 92\nEmail: info@luisemoebel.com"]},{title:"3. Hosting",paragraphs:["This website is hosted on GitHub Pages. When the website is accessed, the hosting provider automatically collects general information such as the IP address of the requesting computer. This data is collected exclusively for technical necessity."]},{title:"4. Your Rights",paragraphs:["You have the right at any time to receive free information about the origin, recipient, and purpose of your stored personal data. You also have the right to request the correction or deletion of this data. If you have given consent for data processing, you can revoke this consent at any time for the future.","For this and other questions regarding data protection, you can contact us at any time."]},{title:"5. Cookies",paragraphs:["This website uses technically necessary cookies to ensure the operation of the site. The cookie for cookie consent (luisemoebel_cookie_consent) only stores your decision regarding cookie usage.","No tracking cookies, marketing cookies, or third-party cookies are used."]},{title:"6. External Links",paragraphs:["This website contains links to external websites (e.g., luisemoebel.com shop, Google Maps). When you click on these links, you leave our website. The respective operators are responsible for data processing on the linked pages."]},{title:"7. SSL Encryption",paragraphs:['This site uses SSL encryption for security reasons. You can recognize an encrypted connection by the fact that the browser address bar changes from "http://" to "https://".']}]},agb:{heroTitle:"Terms and Conditions",heroSubtitle:"LEGAL INFORMATION",sections:[{title:"1. Scope of Application",paragraphs:["These General Terms and Conditions (GTC) apply to all contracts between Luisemöbel, Julius-Heß-Straße 9, 96515 Sonneberg, and the customer. Deviating conditions of the customer are not recognized unless Luisemöbel expressly agrees to their applicability in writing."]},{title:"2. Conclusion of Contract",paragraphs:['The presentation of products on the website does not constitute a legally binding offer, but rather a non-binding online catalog. By clicking the "Buy" button, you place a binding order for the goods contained in the shopping cart.',"Confirmation of receipt of the order, together with acceptance of the contract, is sent automatically by email immediately after the order is placed."]},{title:"3. Prices and Shipping Costs",paragraphs:["All prices are end consumer prices and include statutory value-added tax. Shipping costs are displayed separately and are to be borne by the customer."]},{title:"4. Delivery",paragraphs:["Delivery times are indicated on the product page and in the order confirmation. As these are handcrafted unique pieces, delivery times may vary. Luisemöbel will inform the customer of the expected delivery date.","Delivery is made within Germany and to selected EU countries. Shipping costs depend on the delivery location."]},{title:"5. Retention of Title",paragraphs:["The delivered goods remain the property of Luisemöbel until full payment has been received."]},{title:"6. Right of Withdrawal",paragraphs:["Consumers have the right to withdraw from the contract within fourteen days without giving any reason. The withdrawal period is fourteen days from the day on which you or a third party designated by you takes possession of the goods.","For custom-made furniture pieces produced according to customer specifications, the right of withdrawal may be limited."]},{title:"7. Warranty",paragraphs:["Warranty is provided in accordance with statutory provisions. In the event of a defect, the customer has the choice between subsequent performance through repair or replacement delivery.","Natural characteristics of the wood such as grain, knots, cracks, or color differences do not constitute defects, but are an expression of the uniqueness of natural wood."]},{title:"8. Care Instructions",paragraphs:["Solid wood furniture requires appropriate care. Detailed care instructions are provided with each piece of furniture. Improper care leads to the loss of warranty claims."]},{title:"9. Data Protection",paragraphs:["The collection and processing of personal data is carried out in accordance with our privacy policy."]},{title:"10. Jurisdiction",paragraphs:["Jurisdiction is Sonneberg, Thuringia, Germany. The law of the Federal Republic of Germany applies."]}]},impressum:{heroTitle:"Imprint",heroSubtitle:"LEGAL INFORMATION",companyName:"Luisemöbel",companyAddress:"Julius-Heß-Straße 9\n96515 Sonneberg\nThuringia, Germany",contactTitle:"Contact",contactPhone:"Phone: +49 36 75 40 22 92",contactMobile:"Mobile: +49 16 04 40 26 92",contactEmail:"Email: info@luisemoebel.com",vatTitle:"VAT Identification Number",vatValue:"According to § 27a Value Added Tax Act:\nDE 351 888 707",responsibleTitle:"Responsible for content according to § 55 Abs. 2 RStV",responsibleValue:"Ralf Müller\nJulius-Heß-Straße 9\n96515 Sonneberg",disputeTitle:"EU Dispute Resolution",disputeDesc:"The European Commission provides a platform for online dispute resolution (OS): https://ec.europa.eu/consumers/odr/. Our email address can be found above in the imprint.",consumerTitle:"Consumer Dispute Resolution",consumerDesc:"We are not willing or obliged to participate in dispute resolution proceedings before a consumer arbitration board.",liabilityTitle:"Liability for Content",liabilityDesc:"As a service provider, we are responsible for our own content on these pages in accordance with § 7 Abs.1 TMG under the general laws. However, according to §§ 8 to 10 TMG, we are not obligated as a service provider to monitor transmitted or stored third-party information.",linksTitle:"Liability for Links",linksDesc:"Our offer contains links to external websites of third parties, whose content we have no influence over. Therefore, we cannot assume any liability for these external contents. The respective provider or operator of the pages is always responsible for the content of the linked pages.",copyrightTitle:"Copyright",copyrightDesc:"The content and works created by the site operators on these pages are subject to German copyright law. Duplication, processing, distribution, and any form of commercialization beyond the scope of the copyright law shall require the prior written consent of the respective author or creator."}}},hu:{nav:{home:"Kezdőlap",philosophy:"Filozófia",products:"Termékek",reviews:"Vélemények",contact:"Kapcsolat",shop:"Ugrás a Webshopra"},hero:{tag1:"AKÁCFÁBÓL",tag2:"TERMÉSZETES ÉL",tag3:"KÉZIMUNKA",title1:"A természet művészete",title2:"Az Ön Otthonába",description:"Minden tömörfa asztalunk egyedi darab — a természet formálta, kézzel tökéletesített. Tapasztalja meg az akácfa és a természetes él páratlan szépségét.",cta1:"Felfedezem a Kollekciót",cta2:"Tanácsadás Kérése"},philosophy:{subtitle:"FILOZÓFIÁNK",title:"Bútor Testnek és Léleknek",description1:"Mi egy kis manufaktúra vagyunk a türingiai Sonneberg idilli városából, Németországból. Szakterületünk a különleges. Exkluzív bútorokat készítünk — minden darab kézzel készült, egyedi műremek.",description2:"Exkluzivitás és egyedi design. Munkánk alapja az ügyfelekkel való kommunikáció. Kívánságai megvalósításához kivételes ügyfélszolgálatra van szükség. Az otthon több, mint egy alvóhely — ez egy menedék, a család helye, ahol a lélek szabadon időzhet és igazán jól érezheti magát.",description3:"Egyetlen más anyag sem teremthet több melegséget és otthonosságot, mint a tömörfa. A fa meleg és természetes érzést ad. Célunk olyan bútorokat készíteni, amelyek nemcsak praktikusak és szépek, hanem amelyeken jól érzi magát az ember.",feature1Title:"Tömörfa",feature1Desc:"Minden darab prémium akácfából készül — tartós, gyönyörű és karakteres.",feature2Title:"Kézműves",feature2Desc:"Minden bútordarab kézzel készül műhelyünkben, páratlan minőséget és figyelmet biztosítva.",feature3Title:"Egyedi",feature3Desc:"Két darab sem egyforma. A természetes erezet és él minden asztalt egyedülálló mesterművé tesz."},products:{subtitle:"TERMÉKEINK",title:"Szenvedéllyel Készítve",description:"Fedezze fel kézműves tömörfa bútoraink kollekcióját. Az étkezőasztaloktól a konzolasztalokig — minden darab saját történetét meséli el az akácfa természetes szépségén keresztül.",categories:[{name:"Étkezőasztalok",description:"Lenyűgöző tömörfa étkezőasztalok természetes éllel — az étkezője központi eleme.",link:"https://luisemoebel.com/product-category/esstische/"},{name:"Dohányzóasztalok",description:"Elegáns dohányzóasztalok, amelyek melegséget és karaktert hoznak a nappaliba.",link:"https://luisemoebel.com/product-category/kaffeetische/"},{name:"Konzolasztalok",description:"Stílusos konzolasztalok az előszobába — meleg üdvözlő hazatéréskor.",link:"https://luisemoebel.com/product-category/konsolen/"},{name:"Ülőbútorok",description:"Kényelmes ülőbútorok, amelyek tökéletesen kiegészítik a tömörfa darabokat.",link:"https://luisemoebel.com/product-category/sitzmoebel/"},{name:"Dekoráció",description:"Egyedi dekorációs darabok természetes fából — kis műalkotások az otthonába.",link:"https://luisemoebel.com/product-category/dekoration/"},{name:"Fa Mosdók",description:"Exkluzív fa mosdókagylók — természetes látványosság a fürdőszobában.",link:"https://luisemoebel.com/product-category/holzwaschbecken/"}],viewShop:"Megtekintés a Webshopban"},wood:{subtitle:"A FAANYAGUNK",title:"Az Esőfa — Samanea Saman",description1:"Bútorai gyártásához elsősorban az Esőfa (Samanea Saman) fáit használjuk, amely Suar vagy Chamcha fa néven is ismert. Az Esőfa az Akácfélék családjába tartozik.",description2:"A Suar fa elsősorban lenyűgöző és kontrasztos erezetével ragadja meg a figyelmet, amely fáról fára változik, így minden bútordarab egyedivé válik. A fa nagyon stabil és könnyen megmunkálható, ami egyedülálló bútordarabok létrehozását teszi lehetővé. Természetes olajai védik a kártevőktől és a rothadástól.",description3:"Faanyagunk Észak-Thaiföldről származik. Az Esőfa eredetileg Dél-Amerikából való, de az idő múlásával Ázsia sok részén elterjedt. Az észak-thaiföldi meleg éghajlat és bőséges csapadék optimális feltételeket biztosít az Esőfa növekedéséhez.",sustainability:"Fenntarthatóság",sustainabilityDesc:"Az Esőfa trópusi fa, de nem tartozik a veszélyeztetett vagy védett fajok közé. A thaiföldi Esőfák nem része a természetes esőerdőnek — az infrastruktúra-fejlesztés melléktermékei. Elsősorban árnyékolóként szolgálnak ültetvényeken és utak mentén, fenntartható módon új élőhelyet teremtve."},reviews:{subtitle:"ÜGYFÉLVELEMÉNYEK",title:"Amit Ügyfeleink Mondanak",description:"Ügyfeleink elégedettsége a legnagyobb jutalmunk. Olvassa el, mit mondanak a Luisemöbelnél szerzett tapasztalataikról.",googleLabel:"Google Értékelés",items:[{name:"Teedee",rating:5,text:"Amikor elgondolkodtam rajta, mi lehetne jobb a vásárlási folyamatban, tényleg semmi nem jutott eszembe. Igazán nagyszerű áron kaptunk..."},{name:"S. Stefan - Buzz",rating:5,text:"Hosszas fontolgatás után rendeltem étkezőasztalt. A minőség kiváló! Az asztallap felülete igazi látványosság és a családom..."},{name:"Andre Nolte",rating:5,text:"Müller úr már az első beszélgetéstől nagyon barátságos volt. Rendkívül szakértői tanácsadás. Nagyon gyors szállítás. Az árak kiválóak. Az asztal minősége..."},{name:"Philipp Huber",rating:5,text:"1A szolgáltatás, felülmúlhatatlan ár-érték arány, barátságos és ügyfélközpontú kiszolgálás, rugalmas megoldások és ötletek, az értékesítés után is segítséget nyújt az ápolási kérdésekben. Szívesen újra!"},{name:"Madlin Dittmar",rating:4,text:"2020 novemberében figyeltünk fel a LUISEMÖBEL-re az eBay-en. Rendkívül magas ügyfélközpontúságának köszönhetően már az első telefonhívás után..."},{name:"Matthias Hoeller",rating:5,text:"Müller úr a Luisemöbeltől rendkívül szakértelemmel és türelemmel adott nekünk tanácsot egy természetes fa asztallapú étkezőasztal vásárlásáról, és minden lehetséges erőfeszítést megtett. Bármikor ajánlott!"},{name:"Dr. Jens Barthel",rating:5,text:"Kivételes tanácsadás és támogatás kiváló szolgáltatással."},{name:"Anna Baum",rating:5,text:"Kiváló minőség, jó tanácsadás, kedves személyzet és a távolság ellenére (470 km) szuper szállítás. Csak ajánlani tudom."},{name:"Ramon Langbein",rating:5,text:"Nagyon jó, nagyon ügyfélbarát."},{name:"Joker One",rating:5,text:"Az akácfának tényleg gyönyörű az erezete, és a szép az, hogy egyetlen darabban látható."},{name:"Max Müller",rating:5,text:"Gyönyörűen megmunkált, csodálatos asztalok és még sok más..."},{name:"Thomas Hirt",rating:5,text:"Nagyon szép ötletek és szakértői tanácsadás."}]},contact:{subtitle:"KAPCSOLAT",title:"Lépjen Kapcsolatba Velünk",description:"Kérdése van bútorainkkal kapcsolatban, vagy személyes tanácsadást szeretne? Itt vagyunk Önnek.",phone:"Telefon",mobile:"Mobil / WhatsApp",email:"E-mail",skype:"Skype",address:"Cím",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Türingia, Németország",callUs:"Hívjon Minket",writeUs:"Írjon Nekünk",visitShop:"Látogassa Meg Webshopunkat"},footer:{tagline:"Bútor Testnek és Léleknek — Nemcsak praktikus és szép, hanem amelyeken jól érzi magát az ember. Kézműves tömörfa bútorok kiváló ízlésű, igényes ügyfeleknek.",links:{home:"Kezdőlap",about:"Rólunk",wood:"A faanyagunk",info:"Információk",blog:"Blog",contact:"Kapcsolat",shop:"Webshop",privacy:"Adatvédelmi Irányelvek",terms:"Jogi információk",imprint:"Impresszum"},copyright:"Copyright 2026 © LUISEMOEBEL.com. Minden jog fenntartva.",prices:"*) Minden ár tartalmazza a törvényes áfát, plusz szállítási költségek. Az áthúzott árak az online bolt korábbi árának felelnek meg."},cookie:{title:"Süti Beállítások",description:"Sütiket használunk, hogy a lehető legjobb élményt nyújtsunk weboldalunkon. A weboldal további használatával elfogadja a sütik használatát.",accept:"Összes elfogadása",decline:"Csak szükségesek",settings:"Beállítások",learnMore:"További információ"},subpages:{backToHome:"Vissza a Kezdőlapra",ueberUns:{heroTitle:"Rólunk",heroSubtitle:"TÖBB MINT 25 ÉVE",introTitle:"Történetünk",introP1:"A Luisemöbel több, mint egy bútorgyártó — mi egy manufaktúra, szívvel és lélekkel. Az idilli türingiai Sonnebergben alapítva, elköteleztük magunkat a természetes akácfából készült egyedi bútorok művészete iránt.",introP2:"Több mint 25 éve ötvözzük a hagyományos kézművességet a modern dizájnnal. Minden bútordarab, amely elhagyja műhelyünket, tapasztalt művészeink aláírását és a fa természetes szépségét hordozza.",introP3:"Filozófiánk egyszerű: hiszünk abban, hogy a bútorok többnek kell lenniük, mint funkcionális tárgyaknak. Melegebbé és hívogatóbbá kell tenniük az otthont — bútorok testnek és léleknek.",valuesTitle:"Értékeink",value1Title:"Tömörfa",value1Desc:"Kizárólag prémium akácfát (Esőfa) használunk — nincs furnér, nincs forgácslemez. Tömör, természetes és karakteres.",value2Title:"Kézműves",value2Desc:"Minden bútordarab gondos kézi munkával készül sonnebergi műhelyünkben. Hagyományos kézművesség találkozik egyedi tervezéssel.",value3Title:"Egyedi",value3Desc:"Két darab sem egyforma. A természetes erezet és az egyedi természetes él minden asztalt megismételhetetlen mesterművé tesz.",workshopTitle:"Műhelyünk",workshopDesc:"Sonnebergi műhelyünkben, Türingiában készülnek az Ön álombútorai. Itt tapasztalt művészek szenvedéllyel és precizitással dolgoznak minden egyes darabon. A fa kiválasztásától az utolsó fényesítésig — minden lépést a legnagyobb gondossággal hajtanak végre.",workshopDesc2:"Különös hangsúlyt fektetünk az ügyfelekkel való kommunikációra. Mert csak akkor tudunk olyan bútorokat készíteni, amelyek igazán Önhöz illenek, ha pontosan megértjük kívánságait. A személyes tanácsadás és az egyedi kiszolgálás számunkra nem üres szavak, hanem megélt gyakorlat.",ctaTitle:"Fedezze Fel Kollekciónkat",ctaDesc:"Látogassa meg webshopunkat, és találja meg következő álombútorát.",ctaButton:"Ugrás a Webshopra"},holz:{heroTitle:"A Faanyagunk",heroSubtitle:"TISZTA TERMÉSZET",introTitle:"Az Esőfa — Samanea Saman",introP1:"Bútorai gyártásához elsősorban az Esőfa (Samanea Saman) fáit használjuk, amely Suar vagy Chamcha fa néven is ismert. Az Esőfa az Akácfélék családjába tartozik (Fabaceae, Mimosoideae alcsalád).",introP2:"A Suar fa elsősorban lenyűgöző és kontrasztos erezetével ragadja meg a figyelmet, amely fáról fára változik, így minden bútordarab egyedivé válik. A fa nagyon stabil és könnyen megmunkálható, ami egyedülálló bútordarabok létrehozását teszi lehetővé. Természetes olajai védik a kártevőktől és a rothadástól.",acaciaTitle:"Az Akácfélék Családja",acaciaDesc:"Az Esőfa (Samanea Saman) a Fabaceae (hüvelyesek) családjába és a Mimosoideae alcsaládba tartozik. Bár köznapi nevén gyakran akácnak nevezik, valójában az akácok közeli rokona. A Mimosoideae alcsalád mintegy 80 nemzetséget és körülbelül 3 200 fajt foglal magában, amelyek főleg a trópusi és szubtrópusi régiókban elterjedtek.",acaciaDesc2:"Ezen családra jellemző a szárnyas levelek és a gömbös virágzat. Az Esőfa lenyűgöző méreteket érhet el: akár 40 méteres koronaterjedés és 2 méter feletti törzsátmérő sem ritka.",originTitle:"Származás: Észak-Thaiföld",originDesc:"Faanyagunk Észak-Thaiföldről származik. Az Esőfa eredetileg Dél-Amerikából való, de az idő múlásával Ázsia sok részén elterjedt. Az észak-thaiföldi meleg éghajlat és bőséges csapadék optimális feltételeket biztosít az Esőfa növekedéséhez.",originDesc2:"Észak-Thaiföldön az Esőfa főleg ültetvényeken és utak mentén nő, ahol árnyékolóként szolgál. A fákat akkor aratják le, amikor elérik természetes korukat, vagy amikor az infrastruktúra-fejlesztés miatt el kell távolítani őket.",sustainabilityTitle:"Fenntarthatóság",sustainabilityP1:"Az Esőfa trópusi fa, de nem tartozik a veszélyeztetett vagy védett fajok közé. A thaiföldi Esőfák nem része a természetes esőerdőnek — az infrastruktúra-fejlesztés melléktermékei.",sustainabilityP2:"Elsősorban árnyékolóként szolgálnak ültetvényeken és utak mentén, fenntartható módon új élőhelyet teremtve. Az Esőfa ráadásul nagyon gyorsan nő, és 15-20 éven belül elérheti a betakarítható méretet. Ez fenntartható faforrássá teszi, amely nem az esőerdő rovására történik.",propertiesTitle:"Fa Tulajdonságok",prop1Title:"Keménység",prop1Desc:"Közepesen keménytől keményig (Brinell-keménység kb. 3,5-4,0), ideális nagy igénybevételű bútorokhoz.",prop2Title:"Erezet",prop2Desc:"Kontrasztos és egyedi — a meleg arany árnyalatoktól a mély barna és vörös tónusokig.",prop3Title:"Természetes Védelem",prop3Desc:"A fa természetes olajai védik a kártevőktől és a rothadástól, vegyi kezelés nélkül.",prop4Title:"Képstabilitás",prop4Desc:"Természetes tulajdonságai ellenére a fa megfelelő szárítás és megmunkálás esetén nagyon képstabil."},kontakt:{heroTitle:"Kapcsolat",heroSubtitle:"ITT VAGYUNK ÖNNEK",phoneTitle:"Telefon",phoneValue:"+49 36 75 40 22 92",mobileTitle:"Mobil / WhatsApp",mobileValue:"+49 16 04 40 26 92",emailTitle:"E-mail",emailValue:"info@luisemoebel.com",addressTitle:"Cím",addressValue:"Julius-Heß-Straße 9, 96515 Sonneberg / Türingia, Németország",hoursTitle:"Nyitvatartás",hoursWeekday:"Hétfő — Péntek: 9:00 – 18:00",hoursSaturday:"Szombat: megbeszélés szerint",hoursSunday:"Vasárnap: zárva",formTitle:"Írjon Nekünk",formName:"Az Ön Neve",formEmail:"Az Ön E-mail Címe",formSubject:"Tárgy",formMessage:"Az Ön Üzenete",formSend:"Üzenet Küldése",formNote:"* Ez az űrlap csak megjelenítési célokat szolgál. Nem történik adatátvitel.",mapTitle:"Hogyan Talál Meg Minket",mapButton:"Megnyitás Google Térképen",visitShop:"Webshop Meglátogatása"},datenschutz:{heroTitle:"Adatvédelmi Irányelvek",heroSubtitle:"JOGI INFORMÁCIÓK",sections:[{title:"1. Adatvédelem egy pillantásra",paragraphs:["Általános tájékoztatás: Az alábbi tájékoztatás egyszerű áttekintést ad arról, mi történik a személyes adataival, amikor meglátogatja ezt a weboldalt. Személyes adatok minden olyan adat, amelyekkel személyesen azonosítható.","Adatgyűjtés ezen a weboldalon: Ez a weboldal statikus oldalként működik, szerveroldali adatfeldolgozás nélkül. Személyes adatokat nem tárolunk adatbázisokban. A kapcsolatfelvételi űrlapok csak megjelenítési célokat szolgálnak, és nem továbbítanak adatokat.","Sütik: Ez a weboldal technikai sütiket használ, amelyek a oldal működéséhez szükségesek (pl. süti-hozzájárulás). Nem használunk nyomkövető sütiket vagy elemző eszközöket."]},{title:"2. Felelős Szervezet",paragraphs:["A weboldal adatfeldolgozásáért felelős:\n\nLuisemöbel\nJulius-Heß-Straße 9\n96515 Sonneberg\nTüringia, Németország\n\nTelefon: +49 36 75 40 22 92\nE-mail: info@luisemoebel.com"]},{title:"3. Hosting",paragraphs:["Ez a weboldal a GitHub Pages-en van tárolva. A weboldal megtekintésekor a tárhelyszolgáltató automatikusan általános információkat gyűjt, mint például a hívó számítógép IP-címe. Ezeket az adatokat kizárólag technikai szükségesség miatt gyűjtik."]},{title:"4. Az Ön Jogai",paragraphs:["Bármikor jogában áll ingyenes tájékoztatást kapni a tárolt személyes adatai eredetéről, címzettjéről és céljáról. Emellett joga van ezen adatok helyesbítését vagy törlését kérni. Ha hozzájárulást adott az adatfeldolgozáshoz, ezt a hozzájárulást bármikor visszavonhatja a jövőre nézve.","Ezzel kapcsolatban, valamint az adatvédelemmel kapcsolatos egyéb kérdésekben bármikor fordulhat hozzánk."]},{title:"5. Sütik",paragraphs:["Ez a weboldal technikailag szükséges sütiket használ a oldal működésének biztosítására. A süti-hozzájárulás cookie (luisemoebel_cookie_consent) csak a süti-használattal kapcsolatos döntését tárolja.","Nem használunk nyomkövető sütiket, marketing sütiket vagy harmadik fél sütijeit."]},{title:"6. Külső Hivatkozások",paragraphs:["Ez a weboldal külső weboldalakra mutató hivatkozásokat tartalmaz (pl. luisemoebel.com webshop, Google Térkép). Ezekre a hivatkozásokra kattintva elhagyja weboldalunkat. A hivatkozott oldalakon történő adatfeldolgozásért azok üzemeltetői felelősek."]},{title:"7. SSL Titkosítás",paragraphs:['Ez az oldal biztonsági okokból SSL titkosítást használ. A titkosított kapcsolatot onnan ismerheti fel, hogy a böngésző címsora „http://"-ról „https://"-ra vált.']}]},agb:{heroTitle:"Általános Szerződési Feltételek",heroSubtitle:"JOGI INFORMÁCIÓK",sections:[{title:"1. Hatály",paragraphs:["Ezek az Általános Szerződési Feltételek (ÁSZF) a Luisemöbel, Julius-Heß-Straße 9, 96515 Sonneberg és az ügyfél közötti összes szerződésre vonatkoznak. Az ügyfél eltérő feltételeit nem ismerjük el, kivéve, ha a Luisemöbel írásban kifejezetten elfogadja azok érvényességét."]},{title:"2. Szerződéskötés",paragraphs:['A termékek bemutatása a weboldalon nem minősül jogilag kötelező ajánlatnak, hanem kötelezettség nélküli online katalógusnak. A „Vásárlás" gombra kattintva Ön kötelező megrendelést ad le a kosárban található árukra vonatkozóan.',"A megrendelés beérkezésének megerősítése a szerződés elfogadásával együtt automatikusan e-mailben történik a megrendelés elküldését követően."]},{title:"3. Árak és Szállítási Költségek",paragraphs:["Minden ár végfelhasználói ár, és tartalmazza a törvényes áfát. A szállítási költségeket külön tüntetjük fel, és az ügyfél viseli."]},{title:"4. Szállítás",paragraphs:["A szállítási időket a termékoldalon és a megrendelés-megerősítésben tüntetjük fel. Mivel kézműves egyedi darabokról van szó, a szállítási idők változhatnak. A Luisemöbel tájékoztatja az ügyfelet a várható szállítási időpontról.","A szállítás Németországon belül és kiválasztott EU-országokba történik. A szállítási költségek a szállítási helytől függenek."]},{title:"5. Tulajdonfenntartás",paragraphs:["A szállított áru a teljes fizetésig a Luisemöbel tulajdona marad."]},{title:"6. Elállási Jog",paragraphs:["A fogyasztóknak joguk van tizennégy napon belül indoklás nélkül elállni a szerződéstől. Az elállási határidő tizennégy nap az attól a naptól számítva, amelyen Ön vagy az Ön által megnevezett harmadik személy birtokba vette az árut.","Az ügyfélspecifikációk szerint készített egyedi bútorok esetén az elállási jog korlátozott lehet."]},{title:"7. Jótállás",paragraphs:["A jótállás a törvényes előírások szerint történik. Hibák esetén az ügyfél választhat az utólagos teljesítés között: javítás vagy pótszállítás.","A fa természetes jellemzői, mint az erezet, csomók, repedések vagy színkülönbségek nem minősülnek hibának, hanem a természetes fa egyediségének kifejeződése."]},{title:"8. Ápolási Utasítások",paragraphs:["A tömörfa bútorok megfelelő ápolást igényelnek. Részletes ápolási utasításokat minden bútordarabbal szállítunk. Szakszerűtlen ápolás a jótállási igények elvesztéséhez vezet."]},{title:"9. Adatvédelem",paragraphs:["A személyes adatok gyűjtése és feldolgozása az adatvédelmi irányelveink szerint történik."]},{title:"10. Joghatóság",paragraphs:["A joghatóság Sonneberg, Türingia, Németország. A Németországi Szövetségi Köztársaság joga irányadó."]}]},impressum:{heroTitle:"Impresszum",heroSubtitle:"JOGI ADATOK",companyName:"Luisemöbel",companyAddress:"Julius-Heß-Straße 9\n96515 Sonneberg\nTüringia, Németország",contactTitle:"Kapcsolat",contactPhone:"Telefon: +49 36 75 40 22 92",contactMobile:"Mobil: +49 16 04 40 26 92",contactEmail:"E-mail: info@luisemoebel.com",vatTitle:"ÁFA Azonosítószám",vatValue:"Az áfatörvény § 27a alapján:\nDE 351 888 707",responsibleTitle:"A tartalomért felelős a § 55 Abs. 2 RStV szerint",responsibleValue:"Ralf Müller\nJulius-Heß-Straße 9\n96515 Sonneberg",disputeTitle:"EU Vitarendezés",disputeDesc:"Az Európai Bizottság online vitarendezési (OS) platformot biztosít: https://ec.europa.eu/consumers/odr/. E-mail címünk fent található az impresszumban.",consumerTitle:"Fogyasztói Vitarendezés",consumerDesc:"Nem állunk készen, és nem is vagyunk kötelezett részt venni fogyasztóvédelmi békéltető testület előtti vitarendezési eljárásban.",liabilityTitle:"Tartalmi Felelősség",liabilityDesc:"Szolgáltatóként a TMG § 7 Abs.1 alapján felelősek vagyunk ezekben az oldalakon a saját tartalmakért az általános jogszabályok szerint. A TMG §§ 8-10 alapján azonban szolgáltatóként nem vagyunk kötelezett a továbbított vagy tárolt harmadik féltől származó információkat felügyelni.",linksTitle:"Hivatkozásokért Való Felelősség",linksDesc:"Ajánlatunk harmadik fél külső weboldalaira mutató hivatkozásokat tartalmaz, amelyek tartalmára nincs hatásunk. Ezért ezen külső tartalmakért nem vállalhatunk felelősséget. A hivatkozott oldalak tartalmáért mindig az adott szolgáltató vagy üzemeltető felel.",copyrightTitle:"Szerzői Jog",copyrightDesc:"Az oldalüzemeltetők által ezeken az oldalakon létrehozott tartalmak és művek a német szerzői jog hatálya alá tartoznak. A sokszorosítás, feldolgozás, terjesztés és a szerzői jog határain túlmutató bármilyen felhasználás az adott szerző vagy alkotó előzetes írásbeli hozzájárulását igényli."}}}};e.s(["translations",0,t])}]);